import React, { useState } from "react"

export default function Ubicaciones() {
  const [messages, setMessages] = useState([
    {
      type: "bot",
      content: "Que edificio o salon te gustaria saber su ubicacion...",
    },
  ])
  const [inputValue, setInputValue] = useState("")
  const [showMap, setShowMap] = useState(false)

  const handleSendMessage = () => {
    if (!inputValue.trim()) return

    const userMessage = { type: "user", content: inputValue }
    const botResponse = generateBotResponse(inputValue)

    setMessages((prev) => [...prev, userMessage, ...botResponse])
    setInputValue("")
  }

  const generateBotResponse = (userInput) => {
    const input = userInput.toLowerCase()
    if (input.includes("edificio a")) {
      return [
        {
          type: "bot",
          content:
            "Sigue las siguientes indicaciones para que puedes llegar al edificio A, al igual que te dejo una foto del edificio.",
        },
        {
          type: "bot",
          content: "map_only",
          mapImage: "/campus-map-with-route-to-building-a.jpg",
        },
        {
          type: "bot",
          content: "building_image",
          buildingImage: "/university-building-a-exterior-photo.jpg",
        },
        {
          type: "bot",
          content:
            "Si ocupa saber otra ubicacion favor de escribirla en el chat, si quiere salir al menu principal, favro de presionar el boton 'Salir'",
          actions: [{ label: "Salir...", action: "exit" }],
        },
      ]
    }

    return [
      {
        type: "bot",
        content:
          "Lo siento, no tengo información sobre esa ubicación. Por favor, intenta con otro edificio o salón.",
      },
    ]
  }

  const handleActionClick = (action) => {
    if (action === "exit") {
      window.location.href = "/"
    }
  }

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage()
  }

  return (
    <div className="ubicaciones-container">
      {/* Header */}
      <header className="ubicaciones-header">
        <div className="header-left">
          <h1>TalkinPon</h1>
        </div>
        <div className="header-center">
          <h2>Ubicaciones</h2>
        </div>
        <div className="header-right">
          <button onClick={() => setShowMap(!showMap)} title={showMap ? "Ocultar mapa" : "Mostrar mapa"}>
            🗺️
          </button>
          <img src="/university-logo-circular.jpg" alt="Logo" className="logo" />
        </div>
      </header>

      {/* Main Content */}
      <div className="main-content">
        <div className={`chat-section ${showMap ? "half-width" : "full-width"}`}>
          <div className="messages">
            {messages.map((message, index) => (
              <div key={index} className={`message-row ${message.type === "user" ? "user" : "bot"}`}>
                {message.type === "bot" && <img src="/university-logo-circular.jpg" alt="Bot" className="avatar" />}
                <div className={`message-box ${message.type}`}>
                  {message.content === "map_only" ? (
                    <img src={message.mapImage || "/placeholder.svg"} alt="Mapa" className="map-image" />
                  ) : message.content === "building_image" ? (
                    <img src={message.buildingImage || "/placeholder.svg"} alt="Edificio" className="building-image" />
                  ) : (
                    <p>{message.content}</p>
                  )}
                </div>
                {message.type === "user" && <img src="/university-logo-circular.jpg" alt="User" className="avatar" />}
                {message.actions &&
                  message.actions.map((action, idx) => (
                    <button key={idx} className="action-button" onClick={() => handleActionClick(action.action)}>
                      {action.label}
                    </button>
                  ))}
              </div>
            ))}
          </div>

          {/* Input */}
          <div className="input-area">
            <input
              type="text"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Pregunta lo que quieres..."
            />
            <button onClick={handleSendMessage}>Enviar</button>
          </div>
        </div>

        {/* Map */}
        {showMap && (
          <div className="map-section">
            <div className="map-header">
              <h3>Mapa del Campus</h3>
              <button onClick={() => setShowMap(false)}>✕</button>
            </div>
            <img src="/interactive-campus-map-with-buildings-labeled.jpg" alt="Mapa del campus" className="campus-map" />
          </div>
        )}
      </div>
    </div>
  )
}
